function formatDateTime(value: string) {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return parsed.toLocaleString("vi-VN", {
    dateStyle: "short",
    timeStyle: "short",
  });
}

function formatConfidence(value: number | null) {
  if (value === null) {
    return "-";
  }

  const normalized = value > 1 ? value : value * 100;
  return `${Math.max(0, Math.min(100, normalized)).toFixed(0)}%`;
}

function reviewTone(value: string) {
  const normalized = value.toLowerCase();
  if (normalized.includes("fail") || normalized.includes("error") || normalized.includes("reject")) {
    return "destructive" as const;
  }

  if (normalized.includes("review") || normalized.includes("pending") || normalized.includes("correction")) {
    return "secondary" as const;
  }

  return "outline" as const;
}

