"export default function KnowledgeMap({ highlightNodeId, onClearHighlight }: { highlightNodeId?: string; onClearHighlight?: () => void }) {
  // Hàm sinh URL GitHub để xem mã nguồn trực tuyến
  const getGithubUrl = (path: string) => {
    if (!path) return "#";
    const cleanPath = path
      .replace(/^[dD]:[/\\]EatFitAI_v1[/\\]?/, "")
      .replace(/\\/g, "/");
    return `https://github.com/AnthonyCongHieu/EatFitAI_v1/blob/codex/admin-control-plane-v1/${cleanPath}`;
  };

  // Zoom ban đầu và Pan đứng im cân đối
  const [selectedNodeId, setSelectedNodeId] = useState<string>("nutri-profile");
  const [zoom, setZoom] = useState<number>(1.05); // Mặc định zoom lớn hơn
  const [pan, setPan] = useState<{ x: number; y: number }>({ x: 20, y: 20 });
  const [isPanning, setIsPanning] = useState<boolean>(false);
  const [startPan, setStartPan] = useState<{ x: number; y: number }>({ x: 0, y: 0 });

  const [activeFlowId, setActiveFlowId] = useState<string | null>(null);"

