"  // Hàm tính toán vị trí động của các nodes để tự động sắp xếp lại cực kỳ thông minh khi xem luồng
  const getNodeCoords = (node: KnowledgeNode) => {
    if (activeFlowId && isFocusStepMode) {
      const flow = BUSINESS_FLOWS.find(f => f.id === activeFlowId);
      if (flow) {
        const index = flow.nodes.indexOf(node.id);
        if (index !== -1) {
          const N = flow.nodes.length;
          if (N > 5) {
            // Sắp xếp các node thành 2 hàng hình chữ nhật khép kín (vòng lặp) cực kỳ thoáng đãng và dễ nhìn
            const half = Math.ceil(N / 2);
            const isSecondRow = index >= half;
            // Hàng 1 đi từ trái qua phải, Hàng 2 đi ngược từ phải qua trái tạo thành vòng lặp khép kín
            const col = isSecondRow ? (N - 1) - index : index;

            const startX = 120;
            const spacingX = 265; // Dãn rộng từ 245 -> 265
            const x = startX + col * spacingX;
            const y = isSecondRow ? 450 : 200;
            return { x, y };
          } else {
            // Dưới 5 nodes: Xếp thẳng hàng ngang ở giữa y = 320 cực kỳ đơn giản
            const startX = 200;
            const spacingX = 270; // Dãn rộng từ 250 -> 270
            const x = startX + index * spacingX;
            const y = 320;
            return { x, y };
          }
        }
      }
    }
    return { x: node.x, y: node.y };
  };"

